      'admin.template_mappings.tip' => 'Tip: You can combine free text and placeholders, e.g. <code>{{student.first_name}} {{student.last_name}}</code>. Field references are supported via <code>{{field:promoted}}</code>. Conditional blocks are supported as well: <code>{{student.absence_days_total>0?}}Absences: {{student.absence_days_total}}{{?}}</code>, <code>{{field:promoted>0?}}Promoted to next grade.{{?}}</code>, or content checks like <code>{{ag.sentence?}}...{{?}}</code>. In multiline fields, line breaks can be entered with Enter. Values are stored in <code>template_fields.meta_json.system_binding_tpl</code> (and additionally in <code>system_binding</code> when the template is exactly one placeholder for backwards compatibility).',
